// Showdown's card table, read from the card catalog (.kiro/specs/duel-card-pipeline/cards/,
// generated by scripts/sync-card-specs.mjs). This file defines what the catalog's keyword and
// effect ids mean; cards that exist only in Showdown so far are marked `fresh`.
import {SHOWDOWN_SPECS} from "../card-specs.generated.js";

// Every keyword has one fixed meaning, printed on the screen and in cards.csv.
export const KEYWORDS = Object.freeze({
  guard: ["수호", "적은 다른 부대나 기지보다 이 부대를 먼저 공격해야 합니다."],
  quickdraw: ["속사", "제물 없이 소환해도 등장한 턴에 공격할 수 있습니다."],
  ride: ["돌파", "수호를 가진 적이 없다면 적 부대를 지나쳐 기지에 오브 1개 피해를 줄 수 있습니다."],
  scout: ["정찰", "등장하면 카드를 한 장 뽑습니다."],
  raise: ["소생", "등장하면 묘지에 있는 마지막 언데드 부대가 오브 1개로 돌아옵니다."],
  sweep: ["휩쓸기", "부대를 공격하면 나머지 적 부대가 모두 오브 1개를 잃습니다."],
  laststand: ["최후의 저항", "전투에서 쓰러지면 싸운 부대가 오브 1개를 잃습니다."],
  ghostly: ["유령화", "주문의 대상이 될 수 없습니다."],
});

// How rare a card is, and how many copies one deck may hold. Basic cards have no limit and are never earned.
export const RARITY = Object.freeze({
  basic: ["기본", Infinity], common: ["일반", 4], uncommon: ["고급", 3], rare: ["희귀", 2], legendary: ["전설", 1],
});

// What a spell, trap, gear or location does. `target` says whether the player picks an enemy troop.
// Gear adds to the troop that carries it. A location adds attack to every troop with its tag, on both sides.
export const EFFECTS = Object.freeze({
  shot: {target: true, text: "적 부대 하나에서 오브 1개를 제거합니다."},
  tie: {target: true, text: "적 부대 하나를 기절시킵니다. 다음 턴에 공격할 수 없습니다."},
  hellfire: {target: false, text: "모든 적 부대에서 오브 1개씩 제거합니다."},
  snare: {target: false, text: "함정. 적 부대가 공격하면 먼저 오브 2개를 잃습니다. 그로 인해 쓰러지면 공격은 이루어지지 않습니다."},
  hex: {target: false, text: "함정. 적 부대가 공격하면 그 공격이 취소됩니다."},
  sixshooter: {attack: 1, orbs: 0, text: "장비. 장착한 부대의 공격력이 +1 됩니다."},
  bonearmor: {attack: 0, orbs: 2, text: "장비. 장착한 부대가 오브 2개를 얻습니다."},
  office: {tag: "Lawman", text: "장소. 보안관(Lawman) 부대의 공격력이 +1 됩니다."},
  boneyard: {tag: "Undead", text: "장소. 언데드(Undead) 부대의 공격력이 +1 됩니다."},
});

// One entry per card in the catalog, in catalog order. Lane cards keep the shape they had
// (bounty flag, `keys` on every card); Showdown-only cards are marked `fresh`.
const entry = ({type, side, name, kind, stars, attack, health, bounty, showdownOnly, rarity, tag, keys, effect}) => {
  for (const key of keys ?? []) if (!KEYWORDS[key]) throw new Error(`${type} has unknown keyword ${key}`);
  if (kind !== "troop" && !EFFECTS[effect]) throw new Error(`${type} has unknown effect ${effect}`);
  if (!showdownOnly) {
    return [type, {side, name, kind, stars, attack, health, bounty: Boolean(bounty), keys: keys ?? [], rarity, ...(kind === "troop" ? {tag} : {effect})}];
  }
  return [type, kind === "troop"
    ? {side, name, rarity, kind, stars, attack, health, tag, keys, fresh: true}
    : {side, name, rarity, kind, effect, fresh: true}];
};

export const TYPES = Object.freeze(Object.fromEntries(SHOWDOWN_SPECS.map(entry)));

export const typeOf = (cardId) => cardId.replace(/-\d+$/, "");
export const cardOf = (cardId) => TYPES[typeOf(cardId)];
export const has = (cardId, key) => cardOf(cardId).keys?.includes(key) ?? false;
// 1 to 4 stars are free, 5 and 6 cost one tribute, 7 and up cost two (the main game's rule).
export const tributes = (cardId) => (cardOf(cardId).stars >= 7 ? 2 : cardOf(cardId).stars >= 5 ? 1 : 0);

// Sixteen-card decks for the even match. Gear and locations are earned, so they are not in these.
export const DECKS = Object.freeze({
  cowboy: {"cowboy-sheriff": 4, "cowboy-outrider": 2, "cowboy-covered-wagon": 2, "cowboy-billy": 2, "cowboy-ranger": 1,
    "cowboy-dynamiter": 1, "cowboy-mounted-billy": 1, "cowboy-deadeye": 1, "cowboy-lasso": 1, "cowboy-bear-trap": 1},
  wizard: {"wizard-skeleton": 4, "wizard-jack-o-lantern": 1, "wizard-raven-familiar": 1, "wizard-imp": 1, "wizard-bone-wall": 2,
    "wizard-wizard": 2, "wizard-headless-horseman": 1, "wizard-dragon": 1, "wizard-singularity": 1, "wizard-hellfire": 1, "wizard-hex": 1},
});
export const deckIds = (side, counts = DECKS[side]) => Object.entries(counts).flatMap(([type, count]) => Array.from({length: count}, (_, i) => `${type}-${i + 1}`));
